INSERT INTO `infografis_lang` VALUES (14,'en','Legal Reform Index Assessment Variables','<p>Variabel Penilaian Index Reformasi Hukum</p>'),(14,'id','Variabel Penilaian Index Reformasi Hukum','<p>Variabel Penilaian Index Reformasi Hukum</p>'),(15,'en','Organisasi dan Tata Kerja Kementerian Koordinator Bidang Pangan','<p>Organisasi dan Tata Kerja Kementerian Koordinator Bidang Pangan</p>'),(15,'id','Organisasi dan Tata Kerja Kementerian Koordinator Bidang Pangan','<p>Organisasi dan Tata Kerja Kementerian Koordinator Bidang Pangan</p>'),(16,'en','Rencana Strategis Kementerian Koordinator Bidang Pangan Tahun 2025-2029','<p>Rencana Strategis Kementerian Koordinator Bidang Pangan Tahun 2025-2029</p>'),(16,'id','Rencana Strategis Kementerian Koordinator Bidang Pangan Tahun 2025-2029','<p>Rencana Strategis Kementerian Koordinator Bidang Pangan Tahun 2025-2029</p>'),(17,'en','Pedoman Pelaksanaan Neraca Komoditas Pangan','<p>Pedoman Pelaksanaan Neraca Komoditas Pangan</p>'),(17,'id','Pedoman Pelaksanaan Neraca Komoditas Pangan','<p>Pedoman Pelaksanaan Neraca Komoditas Pangan</p>'),(18,'en','Pedoman Pemantauan dan Evaluasi,  serta Penyesuaian Rencana Aksi Percepatan Pembangunan Pergaraman Nasional','<p>Pedoman Pemantauan dan Evaluasi, &nbsp;serta Penyesuaian Rencana Aksi Percepatan Pembangunan Pergaraman Nasional&nbsp;</p>'),(18,'id','Pedoman Pemantauan dan Evaluasi,  serta Penyesuaian Rencana Aksi Percepatan Pembangunan Pergaraman Nasional','<p>Pedoman Pemantauan dan Evaluasi, &nbsp;serta Penyesuaian Rencana Aksi Percepatan Pembangunan Pergaraman Nasional&nbsp;</p>'),(19,'en','Pelaksanaan Pemberian Tunjangan Kinerja Bagi Pegawai di Lingkungan Kementerian Koordinator Bidang Pangan','<p>Pelaksanaan Pemberian Tunjangan Kinerja Bagi Pegawai di Lingkungan Kementerian Koordinator Bidang Pangan&nbsp;</p>'),(19,'id','Pelaksanaan Pemberian Tunjangan Kinerja Bagi Pegawai di Lingkungan Kementerian Koordinator Bidang Pangan','<p>Pelaksanaan Pemberian Tunjangan Kinerja Bagi Pegawai di Lingkungan Kementerian Koordinator Bidang Pangan&nbsp;</p>'),(20,'en','Piagam Pengawasan Intern di Kementerian Koordinator Bidang Pangan','<p>Piagam Pengawasan Intern di Kementerian Koordinator Bidang Pangan</p>'),(20,'id','Piagam Pengawasan Intern di Kementerian Koordinator Bidang Pangan','<p>Permenko Bidang Pangan Nomor 3 tahun 2026 tentang Piagam Pengawasan Intern di Kementerian Koordinator Bidang Pangan</p>'),(21,'en','Keterlibatan Tim Koordinasi Penyelenggaraan Program Makan Bergizi Gratis dalam Pelaksanaan Penyelenggaraan Program Makan Bergizi Gratis','<p><span style=\"color:hsl(0,0%,0%);\">≡ƒôó Penguatan Koordinasi untuk Sukseskan Program Makan Bergizi Gratis</span><br><br><span style=\"color:hsl(0,0%,0%);\">Pemerintah terus memperkuat tata kelola penyelenggaraan Program Makan Bergizi Gratis (MBG) melalui Peraturan Menteri Koordinator Bidang Pangan Nomor 4 Tahun 2026 tentang Keterlibatan Tim Koordinasi Penyelenggaraan Program Makan Bergizi Gratis dalam Pelaksanaan Penyelenggaraan Program Makan Bergizi Gratis.</span><br><br><span style=\"color:hsl(0,0%,0%);\">Regulasi ini menegaskan peran Tim Koordinasi dalam mendukung penyelenggaraan Program MBG melalui sinkronisasi, koordinasi, monitoring, evaluasi, hingga penyelesaian pelaksanaan lintas kementerian/lembaga dan pemerintah daerah.</span><br><br><span style=\"color:hsl(0,0%,0%);\">Melalui kolaborasi yang terintegrasi, diharapkan Program MBG dapat berjalan lebih efektif, tepat sasaran, serta memberikan manfaat nyata dalam meningkatkan kualitas gizi masyarakat dan menciptakan sumber daya manusia Indonesia yang unggul</span></p>'),(21,'id','Keterlibatan Tim Koordinasi Penyelenggaraan Program Makan Bergizi Gratis dalam Pelaksanaan Penyelenggaraan Program Makan Bergizi Gratis','<p><span style=\"color:hsl(0, 0%, 0%);\">≡ƒôó Penguatan Koordinasi untuk Sukseskan Program Makan Bergizi Gratis</span><br><br><span style=\"color:hsl(0, 0%, 0%);\">Pemerintah terus memperkuat tata kelola penyelenggaraan Program Makan Bergizi Gratis (MBG) melalui Peraturan Menteri Koordinator Bidang Pangan Nomor 4 Tahun 2026 tentang Keterlibatan Tim Koordinasi Penyelenggaraan Program Makan Bergizi Gratis dalam Pelaksanaan Penyelenggaraan Program Makan Bergizi Gratis.</span><br><br><span style=\"color:hsl(0, 0%, 0%);\">Regulasi ini menegaskan peran Tim Koordinasi dalam mendukung penyelenggaraan Program MBG melalui sinkronisasi, koordinasi, monitoring, evaluasi, hingga penyelesaian pelaksanaan lintas kementerian/lembaga dan pemerintah daerah.</span><br><br><span style=\"color:hsl(0, 0%, 0%);\">Melalui kolaborasi yang terintegrasi, diharapkan Program MBG dapat berjalan lebih efektif, tepat sasaran, serta memberikan manfaat nyata dalam meningkatkan kualitas gizi masyarakat dan menciptakan sumber daya manusia Indonesia yang unggul</span></p>'),(22,'en','Tata Kerja Tim Terpadu Pengendalian Alih Fungsi Lahan Sawah dan Tim Pelaksana Pengendalian Alih Fungsi Lahan Sawah','<p><span style=\"color:hsl(0,0%,0%);\">≡ƒôó Telah Terbit!</span><br><br><span style=\"color:hsl(0,0%,0%);\">Peraturan Menteri Koordinator Bidang Pangan Nomor 2 Tahun 2026 tentang Tata Kerja Tim Terpadu Pengendalian Alih Fungsi Lahan Sawah dan Tim Pelaksana Pengendalian Alih Fungsi Lahan Sawah resmi diterbitkan.</span><br><br><span style=\"color:hsl(0,0%,0%);\">Regulasi ini menjadi langkah strategis dalam memperkuat koordinasi, pengendalian, serta perlindungan lahan sawah guna mendukung ketahanan pangan nasional yang berkelanjutan.</span></p>'),(22,'id','Tata Kerja Tim Terpadu Pengendalian Alih Fungsi Lahan Sawah dan Tim Pelaksana Pengendalian Alih Fungsi Lahan Sawah','<p><span style=\"color:hsl(0, 0%, 0%);\">≡ƒôó Telah Terbit!</span><br><br><span style=\"color:hsl(0, 0%, 0%);\">Peraturan Menteri Koordinator Bidang Pangan Nomor 2 Tahun 2026 tentang Tata Kerja Tim Terpadu Pengendalian Alih Fungsi Lahan Sawah dan Tim Pelaksana Pengendalian Alih Fungsi Lahan Sawah resmi diterbitkan.</span><br><br><span style=\"color:hsl(0, 0%, 0%);\">Regulasi ini menjadi langkah strategis dalam memperkuat koordinasi, pengendalian, serta perlindungan lahan sawah guna mendukung ketahanan pangan nasional yang berkelanjutan.</span></p>');
