INSERT INTO `logs` VALUES (2001,3,'admin-jdihpangan','Admin JDIH Pangan','menu','edit','32','Risalah Pembahasan','{\"parent_id\":\"25\",\"label_id\":\"Risalah Pembahasan\",\"label_en\":\"Risalah Pembahasan\",\"permalink_id\":\"risalah-pembahasan\",\"permalink_en\":\"risalah-pembahasan-en\",\"widget_banner\":{\"old_2589\":\"30\"},\"widget_banner_image\":{\"old_2589\":\"{\\\"path\\\":\\\"assets\\/thumbs\\/images\\/banner\\/cover_1440x400_1024x285_0-518_gemini_generated_image_5gb0ik5gb0ik5gb0.png.webp\\\",\\\"name\\\":\\\"cover_1440x400_1024x285_0-518_gemini_generated_image_5gb0ik5gb0ik5gb0.png.webp\\\",\\\"ext\\\":\\\"webp\\\",\\\"size\\\":36510,\\\"ctime\\\":1767684610,\\\"image-width\\\":1440,\\\"image-height\\\":400}\"},\"alt_id\":null,\"alt_en\":null,\"widget_banner_image-medium\":{\"old_2589\":null},\"widget_banner_image-small\":{\"old_2589\":null},\"widget_banner_subtitle_id\":{\"old_2589\":null},\"widget_banner_subtitle_en\":{\"old_2589\":null},\"widget_banner_title_id\":{\"old_2589\":\"Risalah Pembahasan\"},\"widget_banner_title_en\":{\"old_2589\":\"Risalah Pembahasan\"},\"widget_file\":{\"old_2590\":\"31\",\"old_2591\":\"32\",\"old_2592\":\"33\",\"old_2593\":\"34\",\"old_2594\":\"35\",\"old_2595\":\"36\",\"old_2596\":\"37\",\"old_2597\":\"38\",\"old_2598\":\"39\",\"old_2599\":\"40\",\"old_2600\":\"41\",\"old_2601\":\"42\",\"old_2602\":\"43\",\"45\":\"44\"},\"widget_file_title_id\":{\"old_2590\":\"Risalah Pembahasan Rancangan Peraturan Menteri Konservasi Sumber Daya Ikan\",\"old_2591\":\"Risalah Pembahasan Rapat  Harmonisasi Rancangan Permenko tentang Pedoman Pelaksanaan Neraca Komoditas Pangan\",\"old_2592\":\"Risalah Pembahasan Rapat Pembahasan Rancangan Instruksi Presiden  tentang Percepatan Peningkatan Konektivitas Jalan Daerah untuk  Mendukung Swasembada Pangan dan Energi\",\"old_2593\":\"Risalah Pembahasan Rapat Harmonisasi Rancangan Peraturan Presiden tentang  Rencana Pangan Nasional Tahun 2025-2029\",\"old_2594\":\"Risalah Pembahasan Rapat Tim Kecil Harmonisasi Rancangan Peraturan Presiden  tentang Penguatan Logistik Nasional\",\"old_2595\":\"Risalah Pembahasan Rapat Koordinasi Kebijakan Pelaksanaan Perpres 40 Tahun  2023 tentang Percepatan Swasembada Gula Nasional Dan  Penyediaan Bioetanol Sebagai Bahan Bakar Nabati (Biofuel)\",\"old_2596\":\"Risalah Pembahasan Teknis dalam rangka Revisi PP Nomor 13  Tahun 2017 tentang Perubahan Atas PP Nomor 26 Tahun 2008  tentang RTRWN\",\"old_2597\":\"Rapat Permohonan Pengharmonisasian Rancangan  Peraturan Menteri Koordinator Bidang Pangan tentang Perubahan atas  Peraturan Menteri Koordinator Bidang Pangan Nomor 1 Tahun 2024  tentang Organisasi dan Tata Kerja Kementerian Koordinator Bidang  Pangan\",\"old_2598\":\"Risalah Pembahasan Rapat Harmonisasi R-Permenko tentang Tata Kerja Tim Terpadu Pengendalian Alih Fungsi Lahan Sawah dan Tim Pelaksana Pengendalian Alih Fungsi Lahan Sawah\",\"old_2599\":\"Risalah Pembahasan Harmonisasi Tata Naskah Dinas Di Lingkup Kementerian Koordinator Bidang Pangan\",\"old_2600\":\"Risalah Pembahasan Harmonisasi RPermenko Piagam Pengawasan Intern Kementerian  Koordinator Bidang Pangan\",\"old_2601\":\"Risalah Pembahasan Rapat Harmonisasi R-Permenko Bidang Pangan tentang  Keterlibatan Tim Koordinasi Penyelenggaraan Program  Makan Bergizi Gratis\",\"old_2602\":\"Risalah Pembahasan Rapat Harmonisasi Rancangan Peraturan Menteri Koordinator Bidang  Pangan tentang Perubahan Kedua atas Peraturan Menteri Koordinator Bidang  Pangan Nomor 1 Tahun 2024 tentang Organisasi dan Tata Kerja Kementerian  Koordinator Bidang Pangan\",\"45\":\"RAPAT HARMONISASI RANCANGAN PERATURAN MENTERI KOORDINATOR  BIDANG PANGAN TENTANG PERUBAHAN ATAS PERATURAN MENTERI  KOORDINATOR BIDANG PANGAN NOMOR 4 TAHUN 2025 TENTANG PEMBERIAN  TUNJANGAN KINERJA BAGI PEGAWAI DI LINGKUNGAN KEMENTERIAN  KOORDINATOR BIDANG PANGAN\"},\"widget_file_title_en\":{\"old_2590\":\"Risalah Pembahasan Rancangan Peraturan Menteri Konservasi Sumber Daya Ikan\",\"old_2591\":\"Risalah Pembahasan Rapat  Harmonisasi Rancangan Permenko tentang Pedoman Pelaksanaan Neraca Komoditas Pangan\",\"old_2592\":\"Risalah Pembahasan Rapat Pembahasan Rancangan Instruksi Presiden  tentang Percepatan Peningkatan Konektivitas Jalan Daerah untuk  Mendukung Swasembada Pangan dan Energi\",\"old_2593\":\"Risalah Pembahasan Rapat Harmonisasi Rancangan Peraturan Presiden tentang Rencana Pangan Nasional Tahun 2025-2029\",\"old_2594\":\"Risalah Pembahasan Rapat Tim Kecil Harmonisasi Rancangan Peraturan Presiden  tentang Penguatan Logistik Nasional\",\"old_2595\":\"Risalah Pembahasan Rapat Koordinasi Kebijakan Pelaksanaan Perpres 40 Tahun 2023 tentang Percepatan Swasembada Gula Nasional Dan Penyediaan Bioetanol Sebagai Bahan Bakar Nabati (Biofuel)\",\"old_2596\":\"Risalah Pembahasan Teknis dalam rangka Revisi PP Nomor 13 Tahun 2017 tentang Perubahan Atas PP Nomor 26 Tahun 2008 tentang RTRWN\",\"old_2597\":\"Risalah Pembahasan Rapat Permohonan Pengharmonisasian R-Permenko Bidang Pangan tentang Perubahan atas  Permenko Bidang Pangan Nomor 1 Tahun 2024  tentang Organisasi dan Tata Kerja Kemenko Bidang  Pangan\",\"old_2598\":\"Risalah Pembahasan Rapat Harmonisasi R-Permenko tentang Tata Kerja Tim Terpadu Pengendalian Alih Fungsi Lahan Sawah dan Tim Pelaksana Pengendalian Alih Fungsi Lahan Sawah\",\"old_2599\":\"Risalah Pembahasan Rapat Harmonisasi Tata Naskah Dinas Di Lingkup Kementerian Koordinator Bidang Pangan\",\"old_2600\":\"Risalah Pembahasan Rapat Harmonisasi RPermenko Piagam Pengawasan Intern Kementerian  Koordinator Bidang Pangan\",\"old_2601\":\"Risalah Pembahasan Rapat Harmonisasi R-Permenko Bidang Pangan tentang  Keterlibatan Tim Koordinasi Penyelenggaraan Program  Makan Bergizi Gratis\",\"old_2602\":\"Risalah Pembahasan Rapat Harmonisasi Rancangan Peraturan Menteri Koordinator Bidang  Pangan tentang Perubahan Kedua atas Peraturan Menteri Koordinator Bidang  Pangan Nomor 1 Tahun 2024 tentang Organisasi dan Tata Kerja Kementerian  Koordinator Bidang Pangan\",\"45\":\"Risalah Pembahasan Ra