DROP TABLE IF EXISTS `metadata_fields`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `metadata_fields` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `master_document_id` int(10) unsigned NOT NULL,
  `key` varchar(60) NOT NULL,
  `label` varchar(150) NOT NULL,
  `label_en` varchar(150) DEFAULT NULL,
  `type` varchar(20) NOT NULL DEFAULT 'text',
  `options` text DEFAULT NULL,
  `source_column` varchar(60) DEFAULT NULL,
  `is_required` tinyint(1) NOT NULL DEFAULT 0,
  `show_in_public` tinyint(1) NOT NULL DEFAULT 1,
  `sort_id` int(11) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `metadata_fields_master_document_id_key_unique` (`master_document_id`,`key`),
  KEY `metadata_fields_master_document_id_index` (`master_document_id`)
) ENGINE=InnoDB AUTO_INCREMENT=114 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

