INSERT INTO `ratings` VALUES (15,'Fina','syarafina.sayoga@gmail.com','Informasi hukum yang dimuat sangat bermanfaat, lengkap, dan up to date, desain dari websitenya juga simple dan modern.',5,1,'2026-01-08 03:47:05','2026-01-08 03:50:00'),(16,'Aditya Zakky Dermawan','ditzakky2207@gmail.com','Jujur ini website sangat informatif dan menarik! terima kasih ya Mas/Mba, semoga selalu dilimpahkan amal jariyah',5,1,'2026-01-08 03:48:42','2026-01-08 03:49:58'),(17,'Hafidz Muzakki','muzakkihafidz29@gmail.com','JDIH Kemenko Pangan sangat membantu dalam penyediaan informasi hukum yang lengkap, akurat, dan mudah diakses. Tampilan sistem rapi dan pencarian regulasi cukup efektif',5,1,'2026-01-08 03:49:55','2026-01-08 03:50:08'),(18,'Rian','dummybdo2929@gmail.com','Layanan JDIH Kemenko Pangan informatif dan responsif. Dokumen hukum tersaji dengan baik, terstruktur, dan memudahkan pengguna dalam mencari regulasi yang dibutuhkan',5,1,'2026-01-08 03:52:20','2026-01-08 03:58:41'),(19,'Muhammad Devarianto','devarianto59@gmail.com','Tampilan bagus, mengakse peraturan  menjadi Lebih mudah',5,1,'2026-01-08 04:03:02','2026-01-08 07:08:23'),(20,'Oca','rosachoerunnisa@gmail.com','web mudah diakses,  design web bagus serta  informasi dalam web lengkap',5,1,'2026-01-08 04:03:09','2026-01-08 07:08:27');
